#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    /* == 是「判断相等」，= 是「赋值」，写混了结果会全错。
       只有偶数和奇数两种情况：判断完偶数，else 里就一定是奇数，
       不用再写第二个条件。 */
    if (n % 2 == 0) {
        printf("even\n");
    } else {
        printf("odd\n");
    }

    return 0;
}

tutorial.code:
int x = 5;
if (x = 0) {                 /* 错：这是赋值，x 变成 0，条件为假 */
    printf("会执行吗\n");     /* 永远不执行 */
}
if (x == 0) {                /* 对：判断相等 */
    printf("x 是 0\n");
}

/* 不推荐：负数会漏判 */
if (n % 2 == 0)      printf("even\n");
else if (n % 2 == 1) printf("odd\n");   /* -3 % 2 等于 -1，这里不成立 */

