#include <stdio.h>

int main() {
    int score;
    scanf("%d", &score);

    /* 从高到低依次判断：只要有一支成立，执行完就跳出整条链，
       所以 else if 里只需写下界，不必再写 score < 90 这样的上界。 */
    if (score >= 90) {
        printf("A\n");
    } else if (score >= 80) {
        printf("B\n");
    } else if (score >= 60) {
        printf("C\n");
    } else {
        printf("D\n");
    }

    return 0;
}

