if (score >= 90) {
    printf("A\n");
} else if (score >= 80) {   /* 隐含条件：score < 90 */
    printf("B\n");
} else if (score >= 60) {
    printf("C\n");
} else {
    printf("D\n");
}

/* 错误示范：95 分会被判成 C */
if (score >= 60)      printf("C\n");
else if (score >= 80) printf("B\n");
else if (score >= 90) printf("A\n");

