#include <stdio.h>

int main() {
    int year;
    scanf("%d", &year);

    /* 口诀：四年一闰，百年不闰，四百年再闰。
       整个条件 = (能被 4 整除 且 不能被 100 整除) 或 (能被 400 整除)
       括号不省：&& 优先级高于 ||，括起来逻辑一眼可见。 */
    if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }

    return 0;
}

