#include <stdio.h>

int main() {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);

    /* 条件运算符是 C 里唯一的三目运算符：
       条件 ? 成立时的值 : 不成立时的值
       分两步比，比把两个 ?: 嵌套在一起好读得多。 */
    int max = a > b ? a : b;   /* 先取 a、b 中较大的那个 */
    max = max > c ? max : c;   /* 再和 c 比一次 */

    printf("%d\n", max);
    return 0;
}

tutorial.body:
条件运算符是 C 里唯一需要三个操作数的运算符，写法是：

条件 ? 值1 : 值2

条件成立取「值1」，不成立取「值2」。它和 if / else 的区别在于：?: 的结果是一个**值**，所以能直接写在赋值的右边、printf 的参数里；而 if 是语句，不能这么用。

max = a > b ? a : b; 等价于

int max;
if (a > b) max = a;
else       max = b;

tutorial.code:
int a = 3, b = 7;
int max = a > b ? a : b;
printf("%d\n", max);   /* 7 */

/* 推荐：分两步 */
int max = a > b ? a : b;
max = max > c ? max : c;

/* 用 if 写同样清楚 */
int m = a;
if (b > m) m = b;
if (c > m) m = c;

