#include <stdio.h>

int main() {
    int month;
    scanf("%d", &month);

    /* switch 从匹配到的 case 开始一直往下执行，直到遇见 break。
       所以结果相同的 case 可以摞在一起，只在最后写一次 printf。 */
    switch (month) {
        case 2:
            printf("28\n");
            break;
        case 4:
        case 6:
        case 9:
        case 11:
            printf("30\n");   /* 上面四个 case 故意共用这一段 */
            break;
        case 1:
        case 3:
        case 5:
        case 7:
        case 8:
        case 10:
        case 12:
            printf("31\n");
            break;
        default:
            printf("invalid\n");  /* 1~12 以外的情况兜底 */
            break;
    }

    return 0;
}

