#include <stdio.h>

int main() {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);

    /* 构成条件：任意两边之和都大于第三边，三个条件缺一不可。
       1 2 3 这种「刚好相等」是退化三角形，不算数（要 > 不能 >=）。 */
    if (a + b > c && a + c > b && b + c > a) {
        printf("Yes\n");

        /* 顺序很重要：等边也满足「有两边相等」，
           所以必须先判三边全等，否则 5 5 5 会被判成 isosceles。 */
        if (a == b && b == c) {
            printf("equilateral\n");
        } else if (a == b || b == c || a == c) {
            printf("isosceles\n");
        } else {
            printf("scalene\n");
        }
    } else {
        printf("No\n");
    }

    return 0;
}

tutorial.code:
if (a + b > c && a + c > b && b + c > a) {
    printf("Yes\n");
} else {
    printf("No\n");
}

if (a == b && b == c) {
    printf("equilateral\n");   /* 三边全等 */
} else if (a == b || b == c || a == c) {
    printf("isosceles\n");     /* 已有两边不等，再有两边相等就是等腰 */
} else {
    printf("scalene\n");
}
